// ============================================================
// COMPTEUR PIECES
// Ne compte comme BONNE que la piece issue d'un cycle complet.
//
// Pourquoi c'est indispensable : quand une securite se declenche (capot,
// DCY, RTH1, RTH2), l'ESP32 force etat_cycle a ATTENTE sans reinitialiser
// temps_debut_cycle. L'evenement ATTENTE qui suit porte donc une
// duree_cycle qui inclut toute la duree de l'arret. Sans garde-fou, cette
// duree parasite etait comptee comme une bonne piece ET venait gonfler le
// temps de production, faussant disponibilite et performance.
//
// Le drapeau est pose par le noeud "Detection defaut machine".
// ============================================================

const cycle = msg.payload.duree_cycle;

const interrompu = flow.get("cycle_interrompu") === true;
flow.set("cycle_interrompu", false);

if (interrompu) {
    const rebuts = (flow.get("nb_rebuts") || 0) + 1;
    flow.set("nb_rebuts", rebuts);

    // La duree n'est PAS ajoutee au temps de production : ce n'est pas du
    // temps de fabrication, c'est de l'arret. La disponibilite en tient
    // compte d'elle-meme, puisqu'elle rapporte la production au temps ecoule.
    node.status({ fill: "red", shape: "ring", text: rebuts + " rebut(s) - cycle interrompu" });
    msg.payload = {
        rebut: true,
        nb_pieces: flow.get("nb_pieces") || 0,
        nb_rebuts: rebuts,
        duree_ecartee: cycle,
        temps_production_total: flow.get("temps_production") || 0
    };
    return msg;
}

const compteur = (flow.get("nb_pieces") || 0) + 1;
flow.set("nb_pieces", compteur);

const tempsProd = (flow.get("temps_production") || 0) + cycle;
flow.set("temps_production", tempsProd);

node.status({ fill: "green", shape: "dot", text: compteur + " piece(s) bonne(s)" });
msg.payload = {
    rebut: false,
    nb_pieces: compteur,
    nb_rebuts: flow.get("nb_rebuts") || 0,
    dernier_cycle: cycle,
    temps_production_total: tempsProd
};
return msg;

// ============================================================
// PREPARER ARCHIVE  --  fiche complete du poste
// Remplace la ligne "date;pieces;temps;cycle" par un enregistrement
// exploitable par le responsable : qui a produit, combien, a quel rythme,
// avec quelle qualite de fonctionnement et combien d'incidents.
// La sortie alimente la feuille "Postes" du classeur roufix_suivi.xlsx :
// les nombres y sont de vrais nombres, triables et calculables.
// ============================================================

const CHEMIN = "C:/Users/GM Louay/OneDrive/Documents/roufix_suivi.xlsx";
const TEMPS_CYCLE_THEORIQUE = 5200;   // ms, identique au noeud "Calcul TRS"

const ouvrier   = flow.get("ouvrier") || "Non renseigne";
const nbPieces  = flow.get("nb_pieces") || 0;
const nbRebuts  = flow.get("nb_rebuts") || 0;
const tempsProd = flow.get("temps_production") || 0;
const debut     = flow.get("debut_poste") || Date.now();
const fin       = Date.now();
const duree     = Math.max(0, fin - debut);

// Indicateurs du poste (memes formules que le calcul temps reel)
const totalEngage = nbPieces + nbRebuts;
const cycleMoyen = totalEngage > 0 ? Math.round(tempsProd / totalEngage) : 0;
const dispo   = duree > 0 ? (tempsProd / duree) * 100 : 0;
const perf    = tempsProd > 0 ? ((totalEngage * TEMPS_CYCLE_THEORIQUE) / tempsProd) * 100 : 0;
// Qualite MESUREE : les cycles interrompus (defaut, capot ouvert) sont
// comptes en rebut par le noeud "Compteur pieces".
const qualite = totalEngage > 0 ? (nbPieces / totalEngage) * 100 : 100;
const trs     = (dispo / 100) * (perf / 100) * (qualite / 100) * 100;
const cadence = duree > 0 ? Math.round(nbPieces / (duree / 3600000)) : 0;

// Incidents survenus pendant CE poste
const registre = (flow.get("diagnostics") || []).filter(d => d.ts >= debut);
const nbReplis = registre.filter(d => d.source === "repli").length;

const arrondi = (v, dec) => Math.round(v * Math.pow(10, dec)) / Math.pow(10, dec);
const fiche = {
    date: new Date(fin).toLocaleDateString('fr-FR'),
    debut: new Date(debut).toLocaleTimeString('fr-FR'),
    fin: new Date(fin).toLocaleTimeString('fr-FR'),
    ouvrier: ouvrier,
    duree_min: Math.round(duree / 60000),
    pieces: nbPieces,
    rebuts: nbRebuts,
    engagees: totalEngage,
    production_min: Math.round(tempsProd / 60000),
    cycle_moyen: cycleMoyen,
    cadence: cadence,
    disponibilite: arrondi(dispo, 1),
    performance: arrondi(perf, 1),
    qualite: arrondi(qualite, 1),
    trs: arrondi(trs, 1),
    incidents: registre.length,
    replis: nbReplis,
    // releve d'equipe, bouton du dashboard, ou tache planifiee de 06:00
    motif: msg.motif || (msg.topic === "cloture" ? "cloture manuelle" : "fin de poste")
};

// Registre consulte par l'onglet du responsable (50 postes conserves)
const postes = flow.get("postes") || [];
postes.unshift(fiche);
flow.set("postes", postes.slice(0, 50));

msg.filename = CHEMIN;
msg.feuille = "Postes";
msg.entete = ["Date", "Heure debut", "Heure fin", "Ouvrier", "Duree poste (min)",
              "Pieces bonnes", "Rebuts", "Pieces engagees", "Temps production (min)", "Cycle moyen (ms)",
              "Cadence (pieces/h)", "Cycle theorique (ms)", "Disponibilite (%)",
              "Performance (%)", "Qualite (%)", "TRS (%)", "Incidents",
              "Replis IA", "Motif de cloture"];
msg.ligne = [fiche.date, fiche.debut, fiche.fin, ouvrier, fiche.duree_min,
             fiche.pieces, fiche.rebuts, fiche.engagees, fiche.production_min, fiche.cycle_moyen,
             fiche.cadence, TEMPS_CYCLE_THEORIQUE, fiche.disponibilite,
             fiche.performance, fiche.qualite, fiche.trs, fiche.incidents,
             fiche.replis, fiche.motif];
msg.largeurs = [11, 11, 11, 18, 17, 14, 9, 15, 20, 16, 17, 18, 16, 15, 12, 10, 10, 10, 18]
               .map(w => ({ wch: w }));

// Autorise la remise a zero des compteurs en bout de chaine
msg.raz = true;

node.status({ fill: "green", shape: "dot", text: ouvrier + " : " + nbPieces + " pieces" });
return msg;

// ============================================================
// RAZ COMPTEURS
// Ne se declenche QUE sur une cloture de poste (msg.raz). Ce noeud est en
// bout de la chaine d'ecriture CSV, partagee avec l'archivage des
// diagnostics : sans ce garde-fou, chaque diagnostic remettrait la
// production du poste a zero.
// ============================================================

if (msg.raz !== true) { return null; }

// La releve d'equipe transmet le nom du nouvel ouvrier
if (msg.nouvel_ouvrier) {
    flow.set("ouvrier", msg.nouvel_ouvrier);
}

flow.set("nb_pieces", 0);
flow.set("nb_rebuts", 0);
flow.set("temps_production", 0);
flow.set("cycle_interrompu", false);
flow.set("debut_poste", Date.now());
flow.set("hist_trs", null);          // les jauges repartent sur le nouveau poste

// Les limites SPC ne sont PAS reinitialisees : elles caracterisent la
// machine, pas l'ouvrier, et leur reapprentissage couterait 10 cycles.

node.warn("Poste cloture - compteurs remis a zero"
        + (msg.nouvel_ouvrier ? " - nouvel ouvrier : " + msg.nouvel_ouvrier : ""));
node.status({ fill: "green", shape: "dot", text: "poste : " + (flow.get("ouvrier") || "non renseigne") });
return null;

const TEMPS_CYCLE_THEORIQUE = 5200;  // ms, mesuré sur le terrain

const nbPieces = flow.get("nb_pieces") || 0;
const nbRebuts = flow.get("nb_rebuts") || 0;      // cycles interrompus
const tempsProd = flow.get("temps_production") || 0;
let debutPoste = flow.get("debut_poste");

// Si le poste n'a jamais été initialisé, on le démarre maintenant
if (!debutPoste) {
    debutPoste = Date.now();
    flow.set("debut_poste", debutPoste);
}

const tempsRequis = Date.now() - debutPoste;

// Disponibilité : temps de production / temps écoulé depuis le début du poste
const dispo = tempsRequis > 0 ? (tempsProd / tempsRequis) : 0;

// Performance : production idéale / production réelle.
const totalEngage = nbPieces + nbRebuts;
// La performance ne porte que sur les BONNES pieces : le temps de
// production n accumule que leurs cycles. Un cycle interrompu a une duree
// parasite (elle inclut l arret), l integrer fausserait le calcul.
const perf = tempsProd > 0 ? ((nbPieces * TEMPS_CYCLE_THEORIQUE) / tempsProd) : 0;

// Qualité : désormais MESURÉE. Une pièce dont le cycle a été interrompu
// (défaut, capot ouvert en cours de rognage) est comptée en rebut par le
// nœud "Compteur pieces". Plus d'hypothèse à 100 %.
const qualite = totalEngage > 0 ? (nbPieces / totalEngage) : 1;

const trs = dispo * perf * qualite;

const val = {
    trs:           Math.round(trs * 1000) / 10,     // en %
    disponibilite: Math.round(dispo * 1000) / 10,
    performance:   Math.round(perf * 1000) / 10,
    qualite:       Math.round(qualite * 1000) / 10
};

// NOUVEAU : aucune piece produite = pas encore d'indicateur exploitable.
// Sans ce garde-fou, les 4 jauges partent a 0 % et s'affichent en rouge
// des le demarrage du poste, ce qui est une fausse alerte.
const demarrage = (totalEngage === 0);

// ============================================================
// NOUVEAU - preparation des elements graphiques du dashboard
// Tout est calcule ici (cote Node-RED) pour que le noeud
// ui_template reste purement declaratif : pas de script dans
// le dashboard, donc aucun risque de blocage de l'IHM.
// ============================================================

// --- Historique glissant pour les mini-courbes (sparklines) ---
const MAX_HIST = 40;
const CLES = ["trs", "disponibilite", "performance", "qualite"];
const hist = flow.get("hist_trs") || { trs: [], disponibilite: [], performance: [], qualite: [] };
CLES.forEach(function (k) {
    if (!Array.isArray(hist[k])) { hist[k] = []; }
    hist[k].push(val[k]);
    if (hist[k].length > MAX_HIST) { hist[k].shift(); }
});
flow.set("hist_trs", hist);

// --- Geometrie des jauges SVG (cercle r=54, arc utile de 240 degres) ---
const CIRC = 339.292;
const ARC = CIRC * 240 / 360;      // 226.2
const GRIS = "#c7cfda";            // teinte neutre : indicateur non significatif

// Code couleur : rouge = action immediate, orange = surveillance, vert = OK
function couleur(cle, v) {
    if (demarrage) { return GRIS; }
    if (cle === "qualite")       { return v >= 99 ? "#2e9e6b" : (v >= 95 ? "#e8952a" : "#e04b52"); }
    if (cle === "performance")   { return v < 75 ? "#e04b52" : (v < 90 ? "#e8952a" : (v <= 110 ? "#2e9e6b" : "#2c5aa0")); }
    if (cle === "disponibilite") { return v < 75 ? "#e04b52" : (v < 85 ? "#e8952a" : "#2e9e6b"); }
    return v < 60 ? "#e04b52" : (v < 75 ? "#e8952a" : "#2e9e6b");   // TRS
}

// Mini-courbe : serie de points SVG normalisee sur 116 x 24.
// Serie plate -> ligne centree (et non collee au bas du cadre).
function sparkline(serie) {
    if (!serie || serie.length < 2) { return ""; }
    const W = 116, H = 24;
    const mini = Math.min.apply(null, serie);
    const maxi = Math.max.apply(null, serie);
    const plate = (maxi - mini) < 0.5;
    const pas = W / (serie.length - 1);
    return serie.map(function (v, i) {
        const y = plate ? (H / 2) : (H - 3 - ((v - mini) / (maxi - mini)) * (H - 6));
        return (i * pas).toFixed(1) + "," + y.toFixed(1);
    }).join(" ");
}

function jauge(cle, titre, max) {
    const v = val[cle];
    const serie = hist[cle];
    const pct = demarrage ? 0 : Math.max(0, Math.min(100, (v / max) * 100));
    const somme = serie.reduce(function (a, b) { return a + b; }, 0);
    return {
        cle: cle,
        titre: titre,
        valeur: v,
        max: max,
        couleur: couleur(cle, v),
        dash: (ARC * pct / 100).toFixed(1) + " " + CIRC,   // arc rempli
        // Bout arrondi seulement si l'arc est visible : evite le point
        // parasite laisse par un stroke-linecap round a 0 %.
        linecap: pct > 1 ? "round" : "butt",
        points: sparkline(serie),
        mini: Math.round(Math.min.apply(null, serie) * 10) / 10,
        maxi: Math.round(Math.max.apply(null, serie) * 10) / 10,
        moy: Math.round((somme / serie.length) * 10) / 10,
        n: serie.length,
        // Alerte visuelle : uniquement sur une mesure etablie (>= 3 releves)
        critique: (!demarrage && serie.length >= 3 && couleur(cle, v) === "#e04b52")
    };
}

const cycleMoyen = nbPieces > 0 ? Math.round(tempsProd / nbPieces) : 0;

msg.payload = {
    // --- champs historiques conserves (compatibilite debug / archives) ---
    nb_pieces: nbPieces,
    nb_rebuts: nbRebuts,
    total_engage: totalEngage,
    disponibilite: val.disponibilite,
    performance: val.performance,
    qualite: val.qualite,
    trs: val.trs,
    temps_poste_min: Math.round(tempsRequis / 60000),

    // --- NOUVEAU : donnees d'affichage du tableau de bord ---
    demarrage: demarrage,
    cycle_moyen: cycleMoyen,
    cycle_theorique: TEMPS_CYCLE_THEORIQUE,
    arc_track: ARC.toFixed(1) + " " + CIRC,
    maj: new Date().toLocaleTimeString('fr-FR'),
    jauges: [
        jauge("trs",           "TRS Global",    100),
        jauge("disponibilite", "Disponibilité", 100),
        jauge("performance",   "Performance",   150),
        jauge("qualite",       "Qualité",       100)
    ]
};

return msg;

// --- Garde-fou qualite -------------------------------------------------
// Une piece issue d'un cycle INTERROMPU n'est pas representative du
// procede : sa duree fausserait la moyenne et les limites de controle.
// Elle est donc exclue de la carte SPC.
if (msg.payload && msg.payload.rebut === true) { return null; }
// -----------------------------------------------------------------------// --- Paramètres ---
const N_BASELINE = 10;        // 30-50 en production
const K_SIGMA = 3;            // limites à ±3σ (règle classique SPC)

const cycle = msg.payload.dernier_cycle;

// --- Phase 1 : apprentissage ---
let baseline = flow.get("baseline") || [];
let limites = flow.get("limites_spc");

if (!limites) {
    baseline.push(cycle);
    flow.set("baseline", baseline);

    if (baseline.length < N_BASELINE) {
        msg.payload = {
            phase: "APPRENTISSAGE",
            progression: baseline.length + "/" + N_BASELINE,
            statut: "OK"
        };
        return msg;
    }

    // Calcul de la moyenne et de l'écart-type
    const moyenne = baseline.reduce((a, b) => a + b, 0) / baseline.length;
    const variance = baseline.reduce((a, b) => a + Math.pow(b - moyenne, 2), 0) / baseline.length;
    const ecartType = Math.sqrt(variance);

    limites = {
        moyenne: Math.round(moyenne),
        sigma: Math.round(ecartType),
        LSC: Math.round(moyenne + K_SIGMA * ecartType),
        LIC: Math.round(moyenne - K_SIGMA * ecartType)
    };
    flow.set("limites_spc", limites);

    node.warn("Baseline etablie : moyenne=" + limites.moyenne + "ms, sigma=" + limites.sigma);
}

// --- Phase 2 : contrôle sur limites figées ---
let statut = "OK";
let alerte = false;

if (cycle > limites.LSC) {
    statut = "DERIVE HAUTE - cycle trop long";
    alerte = true;
} else if (cycle < limites.LIC) {
    statut = "DERIVE BASSE - cycle anormalement court";
    alerte = true;
}

// Détection de tendance : 7 points consécutifs du même côté
let tendance = flow.get("tendance") || 0;
if (cycle > limites.moyenne) {
    tendance = tendance > 0 ? tendance + 1 : 1;
} else {
    tendance = tendance < 0 ? tendance - 1 : -1;
}
flow.set("tendance", tendance);

if (Math.abs(tendance) >= 7 && !alerte) {
    statut = "TENDANCE - " + Math.abs(tendance) + " cycles consecutifs "
        + (tendance > 0 ? "au-dessus" : "en-dessous") + " de la moyenne";
    alerte = true;
}

msg.payload = {
    phase: "CONTROLE",
    cycle: cycle,
    moyenne: limites.moyenne,
    LSC: limites.LSC,
    LIC: limites.LIC,
    statut: statut,
    alerte: alerte
};

return msg;

// ============================================================
// PREPARER PROMPT IA  --  version 5
// Sortie 1 -> Ollama        Sortie 2 -> IHM (faits + attente)
//
// REPARTITION DES ROLES, mesuree et assumee :
//   - Node-RED calcule les FAITS et la GRAVITE. C'est de l'arithmetique,
//     un modele de 1 milliard de parametres s'en montre incapable : mesure
//     faite, il rendait la meme reponse pour un depassement de 58 ms et un
//     depassement de 2608 ms.
//   - L'IA CLASSE les causes et choisit le geste, dans le referentiel
//     correspondant a la gravite. C'est la sa valeur ajoutee.
// Les enum du schema rendent toute reponse hors referentiel impossible.
// ============================================================

const p = msg.payload || {};
const MAINTENANT = Date.now();

// --- 1. Famille de l'alerte ---
let sens = "tendance";
if (p.type_alerte === "defaut")        { sens = "defaut"; }
else if (/HAUTE/i.test(p.statut))      { sens = "long"; }
else if (/BASSE/i.test(p.statut))      { sens = "court"; }

// --- 2. GRAVITE, calculee ici ---
// Une derive de quelques pour cent n'a pas les memes causes qu'un ecart
// massif : la premiere evoque une usure ou un reglage, la seconde un
// blocage ou une panne franche.
const SEUIL_GRAVITE = 0.25;          // 25 % d'ecart relatif
const SEUIL_THERMIQUE = 30;          // degres au-dessus du seuil d'alarme
let niveau = "modere";
let ampleur = "";

if (sens === "long" || sens === "court") {
    const ecartRelatif = p.moyenne ? Math.abs(p.cycle - p.moyenne) / p.moyenne : 0;
    niveau = ecartRelatif >= SEUIL_GRAVITE ? "severe" : "modere";
    ampleur = "- Ecart relatif : " + Math.round(ecartRelatif * 100) + " % de la moyenne de reference";
} else if (sens === "defaut") {
    // La machine n'a pas de sonde de temperature : l'information disponible
    // est le ou les relais thermiques declenches (RTH1 sur M1, RTH2 sur M2).
    // Les deux ensemble signent une cause commune (blocage, alimentation).
    if (p.moteur === "M1+M2") {
        niveau = "severe";
        ampleur = "- Les DEUX relais thermiques ont declenche (M1 et M2)";
    } else if (p.temperature != null) {
        const depassement = p.temperature - 80;
        niveau = depassement >= SEUIL_THERMIQUE ? "severe" : "modere";
        ampleur = "- Depassement du seuil thermique (80 degres) : " + depassement + " degres";
    } else {
        niveau = "modere";
        ampleur = p.moteur ? ("- Relais thermique declenche : " + p.moteur) : "";
    }
}

// --- 3. Referentiel de maintenance ROUFIX, par famille ET par gravite ---
const REF = {
    long: {
        modere: {
            causes: ["Disque abrasif M1 use", "Moteur M1 en sous-regime",
                     "Temporisation de rognage trop longue", "Pression pneumatique insuffisante",
                     "Verin pneumatique de fixation lent"],
            actions: ["Controler l'usure du disque abrasif M1, le remplacer si necessaire",
                      "Controler le reglage de la temporisation de rognage",
                      "Verifier la pression du reseau pneumatique alimentant le verin",
                      "Controler l'alimentation et le regime du moteur M1"]
        },
        severe: {
            causes: ["Bourrage du cable dans la zone de rognage", "Blocage mecanique du disque abrasif",
                     "Verin de fixation bloque en position", "Moteur M1 en defaut ou desaccouple",
                     "Disque abrasif casse ou desserre"],
            actions: ["Consigner la machine et degager le cable de la zone de rognage",
                      "Hors tension, verifier la rotation libre du disque abrasif",
                      "Controler l'accouplement et l'alimentation du moteur M1",
                      "Verifier l'etat et le serrage du disque abrasif"]
        }
    },
    court: {
        modere: {
            causes: ["Temporisation de rognage trop courte", "Capteur de position deregle",
                     "Pression pneumatique trop elevee"],
            actions: ["Controler le reglage de la temporisation de rognage",
                      "Controler le reglage du capteur de position",
                      "Ajuster la pression du reseau pneumatique"]
        },
        severe: {
            causes: ["Cycle avorte : course du verin non effectuee", "Cable non engage : rognage a vide",
                     "Capteur de position defaillant ou en court-circuit", "Moteur M2 en survitesse"],
            actions: ["Verifier que le verin effectue sa course complete",
                      "Verifier la presence et l'engagement du cable dans le guide",
                      "Controler le capteur de position et son cablage",
                      "Controler le regime du moteur M2"]
        }
    },
    defaut: {
        // RTH1 protege M1 (disque abrasif) : l'effort vient de la coupe
        M1: {
            causes: ["Disque abrasif M1 use : effort de coupe excessif",
                     "Blocage ou frottement du disque abrasif",
                     "Ventilation du moteur M1 obstruee",
                     "Cadence trop elevee pour le refroidissement de M1",
                     "Relais thermique RTH1 deregle ou defaillant"],
            actions: ["Laisser refroidir M1, puis controler l'usure du disque abrasif",
                      "Hors tension, verifier la rotation libre du disque abrasif",
                      "Degager et nettoyer la ventilation du moteur M1",
                      "Controler le calibrage du relais thermique RTH1"]
        },
        // RTH2 protege M2 (entrainement du cable) : l'effort vient du cable
        M2: {
            causes: ["Bourrage ou coincement du cable dans le guide",
                     "Cable de section trop importante pour l'entrainement",
                     "Frein ou point dur sur la ligne d'entrainement",
                     "Ventilation du moteur M2 obstruee",
                     "Relais thermique RTH2 deregle ou defaillant"],
            actions: ["Consigner la machine et degager le cable du guide",
                      "Verifier la section du cable et le reglage du guide",
                      "Hors tension, verifier la rotation libre de l'entrainement M2",
                      "Controler le calibrage du relais thermique RTH2"]
        },
        modere: {
            causes: ["Echauffement progressif d'un moteur par usure",
                     "Ventilation ou refroidissement insuffisant",
                     "Cadence trop elevee pour le refroidissement",
                     "Relais thermique deregle ou defaillant"],
            actions: ["Laisser refroidir les moteurs, puis controler leur temperature",
                      "Verifier la ventilation et le degagement des moteurs",
                      "Controler l'usure du disque abrasif M1",
                      "Controler le calibrage des relais thermiques"]
        },
        severe: {
            causes: ["Blocage mecanique du disque abrasif", "Bourrage du cable dans la zone de rognage",
                     "Court-circuit ou defaut d'alimentation du moteur",
                     "Roulement de moteur grippe"],
            actions: ["Consigner la machine avant toute intervention",
                      "Hors tension, verifier la rotation libre du disque abrasif",
                      "Controler l'alimentation et le serrage des connexions de puissance",
                      "Faire intervenir la maintenance de niveau 2"]
        }
    },
    tendance: {
        modere: {
            causes: ["Disque abrasif M1 use", "Moteur M1 en sous-regime",
                     "Pression pneumatique en baisse progressive",
                     "Temporisation de rognage mal reglee", "Capteur de position deregle"],
            actions: ["Controler l'usure du disque abrasif M1",
                      "Verifier la pression du reseau pneumatique",
                      "Controler l'alimentation et le regime du moteur M1",
                      "Controler le reglage de la temporisation de rognage",
                      "Controler le capteur de position et son cablage"]
        }
    }
};
// Sur un defaut thermique, le relais qui a declenche designe l'organe :
// le referentiel est alors cible sur ce moteur plutot que sur la gravite.
let ref;
if (sens === "defaut" && p.moteur && REF.defaut[p.moteur]) {
    ref = REF.defaut[p.moteur];
} else {
    ref = REF[sens][niveau] || REF[sens].modere;
}

// --- 4. Verrou anti-rafale ---
// Une derive persistante leve une alerte a CHAQUE cycle (~5 s) alors qu'un
// diagnostic prend ~10 s : sans verrou les appels s'empilent. On ignore
// donc toute alerte tant qu'un appel est en cours. Le delai de 2 min entre
// deux diagnostics de meme nature ne s'applique que tant que le diagnostic
// precedent est encore affiche : si le procede est revenu dans ses limites
// puis derive a nouveau, l'operateur a un diagnostic neuf sans attendre.
const enCours = (flow.get("ia_en_cours") === true)
             && ((MAINTENANT - (flow.get("ia_debut") || 0)) < 60000);
if (enCours) {
    node.status({ fill: "blue", shape: "ring", text: "appel en cours - alerte ignoree" });
    return null;
}
const DELAI_MIN = 2 * 60 * 1000;
const signature = sens + "/" + niveau;
if (flow.get("diag_anomalie")
    && flow.get("ia_dernier_sens") === signature
    && msg.topic !== "test"
    && (MAINTENANT - (flow.get("ia_dernier_appel") || 0)) < DELAI_MIN) {
    node.status({ fill: "grey", shape: "ring", text: "diagnostic recent - alerte ignoree" });
    return null;
}

// --- 5. Les FAITS : calcules ici, jamais confies au modele ---
const GRAVITE = { modere: "moderee", severe: "severe" };
let anomalieSPC, spc = null, donnees;

if (sens === "defaut") {
    anomalieSPC = "Arrêt sécurité : " + (p.libelle || p.etat)
                + (p.code_defaut ? " (" + p.code_defaut + ")" : "");
    donnees = "- Nature : arret de securite, la production est stoppee"
            + "\n- Cause relevee par l'automate : " + (p.libelle || p.etat)
            + (p.moteur ? "\n- Relais thermique declenche : " + p.moteur : "")
            + (ampleur ? "\n" + ampleur : "")
            + "\n- Pieces produites depuis le debut du poste : " + p.nb_pieces;
} else {
    if (sens === "long") {
        anomalieSPC = "Cycle de " + p.cycle + " ms : " + (p.cycle - p.LSC)
                    + " ms au-dessus de la limite haute (LSC " + p.LSC + " ms)";
    } else if (sens === "court") {
        anomalieSPC = "Cycle de " + p.cycle + " ms : " + (p.LIC - p.cycle)
                    + " ms sous la limite basse (LIC " + p.LIC + " ms)";
    } else {
        anomalieSPC = p.statut + " (moyenne de reference " + p.moyenne + " ms)";
    }
    spc = {
        statut: p.statut, cycle: p.cycle, moyenne: p.moyenne,
        LSC: p.LSC, LIC: p.LIC, ecart: p.cycle - p.moyenne,
        sens: sens, niveau: niveau
    };
    donnees = "- Nature : " + p.statut
            + "\n- Temps de cycle mesure : " + p.cycle + " ms"
            + "\n- Moyenne de reference : " + p.moyenne + " ms"
            + "\n- Ecart a la moyenne : " + (p.cycle - p.moyenne) + " ms"
            + (ampleur ? "\n" + ampleur : "")
            + "\n- Limites de controle : LIC " + p.LIC + " ms / LSC " + p.LSC + " ms";
}

const msgAttente = {
    payload: {
        ia_en_cours: true, anomalie_spc: anomalieSPC,
        spc: spc, famille: sens, gravite: GRAVITE[niveau]
    }
};

// --- 6. Requete Ollama : classement sous contrainte ---
const CONTEXTE = (sens === "defaut")
    ? "La machine vient de s'arreter en securite. Determine l'origine la plus probable de l'arret."
    : "Une carte de controle SPC signale une derive des temps de cycle.";

const PROMPT = `Tu es un technicien de maintenance expert de la machine de rognage de cables ROUFIX.
Organes : moteur M1 (disque abrasif), moteur M2 (entrainement du cable), verin pneumatique de fixation, temporisation de rognage de 3 s, capteurs de position et de securite.
${CONTEXTE}
Gravite evaluee : ${GRAVITE[niveau]}.
CAUSES :
${ref.causes.map((c, i) => (i + 1) + ". " + c).join("\n")}
ACTIONS :
${ref.actions.map((c, i) => (i + 1) + ". " + c).join("\n")}

MESURES :
${donnees}

Classe les causes de la plus probable a la moins probable au vu de ces mesures, retiens les 2 premieres, puis l'action a mener en priorite.`;

msg.payload = {
    model: "llama3.2:1b",
    prompt: PROMPT,
    format: {
        type: "object",
        properties: {
            causes_probables: {
                type: "array",
                items: { type: "string", enum: ref.causes },
                minItems: 2, maxItems: 2
            },
            action_immediate: { type: "string", enum: ref.actions }
        },
        required: ["causes_probables", "action_immediate"]
    },
    stream: false,
    keep_alive: -1,          // modele garde en RAM : evite 7 s de rechargement
    options: {
        // 130 et non 80 : en dessous, la reponse JSON est tronquee en plein
        // milieu et le diagnostic bascule inutilement en repli (mesure).
        num_predict: 130,
        temperature: 0.2,
        top_p: 0.9,
        num_ctx: 1024,
        repeat_penalty: 1.1
    }
};

// Contexte transporte jusqu'a l'IHM, y compris par le chemin d'erreur
msg.spc = spc;
msg.anomalie_spc = anomalieSPC;
msg.famille = sens;
msg.gravite = GRAVITE[niveau];
msg.ia_t0 = MAINTENANT;
msg.requestTimeout = 40000;

flow.set("ia_en_cours", true);
flow.set("ia_debut", MAINTENANT);
flow.set("ia_dernier_appel", MAINTENANT);
flow.set("ia_dernier_sens", signature);

node.status({ fill: "yellow", shape: "dot", text: "diagnostic en cours (" + signature + ")" });

return [msg, msgAttente];

// ============================================================
// FALLBACK IA
// Declenche par le noeud catch "Erreur IA" (scope = http request Ollama).
// Fonctionne reellement depuis que "senderr" est passe a true : timeout,
// service arrete et erreur reseau levent bien une exception captee ici.
//
// Le message d'origine est conserve par le noeud catch : les faits SPC
// (msg.anomalie_spc, msg.spc) restent donc disponibles et continuent
// d'etre affiches meme quand l'IA est injoignable.
// ============================================================

const detail = (msg.error && msg.error.message)
    ? String(msg.error.message).substring(0, 90)
    : "Aucune reponse du service local";

msg.payload = {
    causes_probables: [
        "Service Ollama arrete, surcharge ou delai depasse",
        "Detail technique : " + detail
    ],
    action_immediate: "IA INDISPONIBLE - APPLIQUER LA GAMME DE MAINTENANCE STANDARD (Niv. 1)",
    fallback: true
};

node.status({ fill: "red", shape: "dot", text: "repli : " + detail.substring(0, 30) });
return msg;

// ============================================================
// EXTRAIRE DIAGNOSTIC  --  version robuste
// Assemble le diagnostic affiche : les FAITS viennent de Node-RED
// (msg.anomalie_spc, calcule dans "Preparer prompt IA"), le JUGEMENT
// vient d'Ollama. Si le modele echoue, les faits restent affiches.
// Ne laisse JAMAIS la chaine muette.
// ============================================================

const p = msg.payload;
const dureeIA = msg.ia_t0 ? (Date.now() - msg.ia_t0) : null;

// Une reponse exploitable contient au moins des causes ou une action.
const utilisable = (o) => o && (Array.isArray(o.causes_probables) || o.action_immediate);

// Reponse HTTP en erreur (500, 404...) : Ollama peut repondre 4xx/5xx sans
// lever d'exception, on bascule en repli sans tenter de parsing inutile.
const httpKo = (typeof msg.statusCode === "number" && msg.statusCode >= 400);

let diag = null;
if (!httpKo) {
    // Forme 1 : payload deja au bon format (sortie du noeud "Fallback IA")
    if (utilisable(p)) { diag = p; }
    // Forme 2 : payload = { response: {...} }  (objet deja parse)
    else if (p && typeof p.response === "object" && utilisable(p.response)) { diag = p.response; }
    // Forme 3 : payload = { response: "{...}" }  (chaine JSON, cas nominal)
    else if (p && typeof p.response === "string") {
        try {
            const parsed = JSON.parse(p.response.trim());
            if (utilisable(parsed)) { diag = parsed; }
        } catch (e) {
            node.warn("JSON invalide recu d'Ollama (reponse tronquee ?) : " + p.response);
        }
    }
    // Forme 4 : payload = chaine brute non parsee par le noeud http request
    else if (typeof p === "string") {
        try {
            const parsed = JSON.parse(p);
            const src = (parsed && parsed.response) ? parsed.response : parsed;
            const obj = (typeof src === "string") ? JSON.parse(src) : src;
            if (utilisable(obj)) { diag = obj; }
        } catch (e) {
            node.warn("Reponse Ollama non exploitable : " + p.substring(0, 120));
        }
    }
}

// Normalisation : borne la longueur pour que l'IHM reste lisible
const texte = (v, max) => String(v == null ? "" : v).trim().substring(0, max);

if (diag) {
    const causes = Array.isArray(diag.causes_probables)
        ? diag.causes_probables
        : [diag.causes_probables];

    msg.payload = {
        // Faits mesures : prioritaires sur toute formulation du modele
        anomalie: msg.anomalie_spc || texte(diag.anomalie, 140) || "Derive detectee sur le temps de cycle",
        causes_probables: causes.filter(Boolean).slice(0, 3).map(c => texte(c, 140)),
        action_immediate: texte(diag.action_immediate, 160) || "Verifier la machine",
        fallback: diag.fallback === true,
        spc: msg.spc || null,
        duree_ia: dureeIA
    };
    node.status({
        fill: msg.payload.fallback ? "red" : "green", shape: "dot",
        text: (msg.payload.fallback ? "repli" : "diagnostic") + (dureeIA ? " - " + Math.round(dureeIA / 100) / 10 + " s" : "")
    });
    return msg;
}

// Repli : l'IA n'a rien fourni d'exploitable, les faits restent affiches
node.warn("Fallback IA declenche (statusCode=" + msg.statusCode + "). Payload recu : " + JSON.stringify(msg.payload));
msg.payload = {
    anomalie: msg.anomalie_spc || "Derive detectee sur le temps de cycle",
    causes_probables: [
        httpKo ? ("Service IA en erreur (HTTP " + msg.statusCode + ")")
               : "Service Ollama arrete ou reponse invalide",
        "Diagnostic automatique indisponible"
    ],
    action_immediate: "IA INDISPONIBLE - APPLIQUER LA GAMME DE MAINTENANCE STANDARD (Niv. 1)",
    fallback: true,
    spc: msg.spc || null,
    duree_ia: dureeIA
};
node.status({ fill: "red", shape: "dot", text: "repli - reponse inexploitable" });
return msg;

// ============================================================
// CONSTRUIRE PAYLOAD IHM - fusion memorisee
// Empeche l'ecrasement du diagnostic IA par les messages d'etat
// machine (heartbeats), tient le journal temps reel, et emet
// TOUJOURS un payload complet.
// ============================================================

const p = msg.payload || {};
const MAINTENANT = Date.now();
const hms = new Date(MAINTENANT).toLocaleTimeString('fr-FR');
const heure = hms.substring(0, 5);

// --- Journal temps reel : 6 derniers evenements, tous types confondus ---
const journal = flow.get("journal") || [];
function tracer(type, texte) {
    if (journal.length && journal[0].texte === texte) { return; }   // pas de doublon
    journal.unshift({ h: hms, type: type, texte: texte });
    flow.set("journal", journal.slice(0, 6));
}

const histo = flow.get("diag_historique") || [];

// --- 0. Alerte : les FAITS arrivent avant l'IA ---
// "Preparer prompt IA" emet ce message des la detection, sans attendre
// Ollama. L'operateur voit donc immediatement la mesure en defaut et un
// indicateur de calcul ; les causes et l'action arriveront apres.
if (p.ia_en_cours === true) {
    flow.set("ia_en_cours", true);
    flow.set("ia_debut", MAINTENANT);
    tracer("ia", "Analyse IA lancee (" + (p.famille || "derive") + ")");

    if (p.anomalie_spc) {
        flow.set("diag_anomalie", p.anomalie_spc);
        flow.set("diag_causes", []);          // en attente du jugement IA
        flow.set("diag_action", "");
        flow.set("diag_fallback", false);
        flow.set("diag_spc", p.spc || null);
        flow.set("diag_famille", p.famille || null);
        flow.set("diag_gravite", p.gravite || null);
        flow.set("diag_duree", null);
        flow.set("diag_timestamp", MAINTENANT);
        flow.set("diag_heure", heure);

        // Historique : l'evenement est l'alerte, pas la reponse du modele
        histo.unshift({ heure: heure, anomalie: p.anomalie_spc, repli: false, attente: true });
        flow.set("diag_historique", histo.slice(0, 3));
    }
}

// --- 1. Reponse de l'IA (diagnostic reel OU repli) ---
if (p.anomalie) {
    flow.set("diag_anomalie", p.anomalie);
    flow.set("diag_causes", Array.isArray(p.causes_probables) ? p.causes_probables : []);
    flow.set("diag_action", p.action_immediate || "");
    flow.set("diag_fallback", p.fallback === true);
    flow.set("diag_spc", p.spc || flow.get("diag_spc") || null);
    flow.set("diag_duree", p.duree_ia || null);
    flow.set("diag_timestamp", MAINTENANT);
    flow.set("diag_heure", heure);

    // Le repli empruntant ce meme chemin, l'indicateur d'attente
    // s'eteint dans tous les cas.
    flow.set("ia_en_cours", false);

    const secondes = p.duree_ia ? " en " + (Math.round(p.duree_ia / 100) / 10) + " s" : "";
    tracer(p.fallback === true ? "repli" : "diag",
           (p.fallback === true ? "Repli IA applique" : "Diagnostic IA recu") + secondes);

    // Complete l'entree d'historique creee par l'alerte, sinon en cree une
    if (histo.length && histo[0].attente && histo[0].anomalie === p.anomalie) {
        histo[0].repli = (p.fallback === true);
        delete histo[0].attente;
    } else {
        histo.unshift({ heure: heure, anomalie: p.anomalie, repli: (p.fallback === true) });
    }
    flow.set("diag_historique", histo.slice(0, 3));

    // Registre long conserve pour l'onglet du responsable (50 entrees).
    // L'IHM operateur n'affiche que l'instant present : sans ce registre,
    // tout ce qui s'est passe pendant le poste precedent serait perdu.
    const registre = flow.get("diagnostics") || [];
    registre.unshift({
        ts: MAINTENANT,
        date: new Date(MAINTENANT).toLocaleDateString('fr-FR'),
        heure: hms,
        ouvrier: flow.get("ouvrier") || "",
        famille: flow.get("diag_famille") || "spc",
        anomalie: p.anomalie,
        causes: (Array.isArray(p.causes_probables) ? p.causes_probables : []).join(" / "),
        action: p.action_immediate || "",
        source: (p.fallback === true) ? "repli" : "IA",
        duree_ia: p.duree_ia || null
    });
    flow.set("diagnostics", registre.slice(0, 50));
}


// --- 1 bis. Mesure SPC en temps reel, a chaque piece ---
// "Detection derive" emet une evaluation a chaque cycle. On garde la derniere
// mesure pour l'afficher en continu, et surtout on SOLDE le diagnostic des
// que le procede revient dans ses limites : sans cela le dernier diagnostic
// restait affiche 10 min, meme avec des cycles redevenus bons.
if (p.phase === "APPRENTISSAGE") {
    flow.set("spc_apprentissage", p.progression || null);
    flow.set("spc_cycle", null);
}
if (p.phase === "CONTROLE") {
    flow.set("spc_apprentissage", null);
    flow.set("spc_cycle", p.cycle);
    flow.set("spc_cycle_ok", p.alerte !== true);
    flow.set("spc_limites", { moyenne: p.moyenne, LSC: p.LSC, LIC: p.LIC });

    // Cycle dans les limites : le probleme de cycle est resorbe.
    // Un defaut machine, lui, n'est pas concerne : il se solde au redemarrage.
    if (p.alerte !== true && flow.get("diag_anomalie")) {
        tracer("etat", "Cycle complet a " + p.cycle + " ms - diagnostic solde");
        flow.set("diag_anomalie", null);
        flow.set("diag_causes", []);
        flow.set("diag_action", "");
        flow.set("diag_spc", null);
        flow.set("diag_duree", null);
        flow.set("diag_timestamp", 0);
        flow.set("diag_famille", null);
    }
}

// --- 2. Garde-fou de l'indicateur d'attente ---
// Si ni reponse ni erreur ne revient au bout de 60 s (> timeout de 40 s),
// on eteint l'indicateur : jamais de calcul fige a l'ecran. Ce meme
// drapeau sert de verrou anti-rafale dans "Preparer prompt IA".
const enCours = (flow.get("ia_en_cours") === true)
             && ((MAINTENANT - (flow.get("ia_debut") || 0)) < 60000);
if (!enCours) { flow.set("ia_en_cours", false); }

// --- 3. Etat machine, communication, statut systeme ---
// Meme vocabulaire de defaut que le noeud "Detection defaut machine".
// Meme vocabulaire que le noeud "Detection defaut machine". L'arret NORMAL
// est teste en premier : "ARRET_CAPOT" contient "ARRET" sans etre une panne.
const ARRET_NORMAL = /DCY|DEPART_CYCLE|CAPOT|PORTE|CARTER|PROTECTEUR|PAUSE|REPOS|INIT|PRET|REARM|MANUEL|FIN_CYCLE|ATTENTE/i;
const estDefaut = e => {
    const t = String(e || "");
    return !ARRET_NORMAL.test(t)
        && /SECURITE|URGENCE|THERMIQUE|SURCHAUFFE|RTH|DEFAUT|ALARME|ERREUR|BLOCAGE|BOURRAGE|ARRET/i.test(t);
};

if (p.etat) {
    const avant = flow.get("machine_etat");
    if (avant !== p.etat) {
        tracer("etat", "Etat machine : " + p.etat);
    }
    flow.set("machine_etat", p.etat);
}
// Presence de l'automate : identifiee par le TOPIC et non par la forme du
// payload. Les messages SPC portent eux aussi un champ "statut" ("OK" en
// phase d'apprentissage) : les confondre forcait la liaison a PERTE a
// chaque cycle. Recevoir un message de ce topic vaut presence, sauf si
// l'automate annonce explicitement son absence (message de testament LWT).
if (typeof msg.topic === "string" && /systeme\/statut/i.test(msg.topic)) {
    const texte = String((p && p.statut) || p || "");
    const enLigne = !/hors ligne|offline|deconnect|indisponible|perdu|down/i.test(texte);
    if (flow.get("machine_comm") !== enLigne) { tracer("systeme", "Automate : " + texte); }
    flow.set("machine_comm", enLigne);
}
// Message du watchdog : payload est une chaine texte
if (typeof p === "string") {
    const commOk = p.indexOf("OK") >= 0;
    if (flow.get("machine_comm") !== commOk) {
        tracer("comm", commOk ? "Communication retablie" : "PERTE DE COMMUNICATION");
    }
    flow.set("machine_comm", commOk);
}
// Message structure avec champ communication
if (typeof p.communication !== "undefined") {
    flow.set("machine_comm", p.communication);
}

// --- 4. Classe visuelle de l'etat (hierarchie du dashboard) ---
const etat = flow.get("machine_etat") || "--";
let etatClasse = "idle";
// Un arret d'exploitation (capot, DCY) porte le meme etat "ARRET_SECURITE"
// qu'une panne : seule la nature relevee par le detecteur les separe.
const exploitation = (flow.get("arret_exploitation") === true);
if (estDefaut(etat) && !exploitation) { etatClasse = "bad"; }
else if (/MARCHE|PRODUCTION|CYCLE|ROGNAGE|FIXATION|TEMPORISATION|RETOUR/i.test(etat)) { etatClasse = "ok"; }

// --- 5. Duree de vie du diagnostic ---
// Une derive SPC est un evenement ponctuel : son diagnostic expire au bout
// de 10 min. Un defaut machine, lui, dure tant que la machine est arretee :
// son diagnostic reste affiche jusqu'au redemarrage effectif, sinon la carte
// redeviendrait "nominale" avec une machine toujours en securite.
const DUREE_VALIDITE = 10 * 60 * 1000;
const familleDiag = flow.get("diag_famille");

// L'arret de securite est un EVENEMENT, pas un etat durable : l'ESP32
// repasse aussitot en ATTENTE. Le diagnostic vit donc comme celui d'une
// derive : 10 minutes, ou jusqu'au premier cycle complet.
const diagValide = (MAINTENANT - (flow.get("diag_timestamp") || 0)) < DUREE_VALIDITE;

// --- 6. On emet TOUJOURS un payload complet ---
msg.payload = {
    machine: "ROUFIX 01",
    etat: etat,
    etat_classe: etatClasse,
    communication: flow.get("machine_comm"),

    // Bloc IA : strictement additionnel, jamais bloquant pour ce qui precede
    ia_en_cours: enCours,
    ia_fallback: diagValide ? (flow.get("diag_fallback") === true) : false,
    diag_heure: diagValide ? (flow.get("diag_heure") || "") : "",
    diag_duree: diagValide ? flow.get("diag_duree") : null,
    diag_famille: diagValide ? flow.get("diag_famille") : null,
    spc: diagValide ? flow.get("diag_spc") : null,

    anomalie: diagValide ? flow.get("diag_anomalie") : null,
    causes_probables: diagValide ? (flow.get("diag_causes") || []) : [],
    action_immediate: diagValide ? flow.get("diag_action") : "",

    // Mesure du dernier cycle, rafraichie a chaque piece produite
    dernier_cycle: flow.get("spc_cycle"),
    cycle_ok: flow.get("spc_cycle_ok"),
    apprentissage: flow.get("spc_apprentissage"),
    limites: flow.get("spc_limites") || null,

    ouvrier: flow.get("ouvrier") || "",
    // Arret d'exploitation (DCY non actionne, capot ouvert...) : ce n'est
    // pas une panne, l'IHM doit le dire sans alarmer.
    raison_arret: (etatClasse !== "bad") ? (flow.get("raison_arret") || null) : null,
    arret_exploitation: exploitation,
    diag_gravite: diagValide ? flow.get("diag_gravite") : null,
    nb_rebuts: flow.get("nb_rebuts") || 0,

    historique: flow.get("diag_historique") || [],
    journal: flow.get("journal") || []
};

return msg;

// ============================================================
// DETECTION DEFAUT MACHINE
// Cale sur le vocabulaire REEL de l'ESP32 ROUFIX :
//   etats  : ATTENTE, FIXATION, TEMPORISATION, RETOUR, ARRET_SECURITE
//   defaut : "Aucun", ou concatenation de Capot_Ouvert, Arret_DCY,
//            Defaut_RTH1, Defaut_RTH2 (separes par un espace)
//
// POINT CLE : les quatre causes d'arret publient le MEME etat
// "ARRET_SECURITE". Seul le champ "defaut" permet de distinguer une panne
// (thermique) d'un arret d'exploitation (capot, DCY). C'est donc lui qui
// decide s'il faut un diagnostic IA.
// ============================================================

const p = msg.payload || {};
const etat = String(p.etat || "").toUpperCase();
if (!etat) { return null; }

const code = String(p.defaut || p.code_defaut || p.erreur || "").toUpperCase();
const codePropre = (code === "AUCUN" || code === "SECURITE_RETABLIE") ? "" : code;

const THERMIQUE    = /RTH1|RTH2|THERMIQUE|SURCHAUFFE/;
const EXPLOITATION = /CAPOT|DCY|PORTE|CARTER|PROTECTEUR/;

const estIncident = /ARRET_SECURITE|ARRET_URGENCE|DEFAUT|ALARME|URGENCE|BLOCAGE|BOURRAGE/.test(etat)
                 || THERMIQUE.test(codePropre);

// Une panne prime sur une cause d'exploitation : "Capot_Ouvert Defaut_RTH1"
// est un defaut thermique, pas une simple ouverture de capot.
const estPanne = estIncident
              && (THERMIQUE.test(codePropre) || !EXPLOITATION.test(codePropre));

// --- Front montant ---
// Le firmware corrige repete l'etat de securite dans chaque heartbeat tant
// que la condition persiste. Sans cette signature, on relancerait un
// diagnostic toutes les 10 s et on marquerait a tort les pieces suivantes
// en rebut.
const signature = etat + "|" + codePropre;
const precedent = flow.get("defaut_etat_precedent");
const nouvelIncident = estIncident && (signature !== precedent);
flow.set("defaut_etat_precedent", signature);

// --- Cycle interrompu ---
// Toute coupure casse le cycle en cours. Deux firmwares sont supportes :
//   - corrige : l'evenement ARRET_SECURITE porte la duree du cycle avorte,
//               le rebut est comptabilise immediatement ;
//   - ancien  : la duree vaut 0 ici, mais l'evenement ATTENTE qui suit porte
//               une duree parasite. On arme alors le drapeau, et c'est le
//               noeud "Compteur pieces" qui rebutera cette piece.
// Les deux chemins s'excluent : aucun double comptage possible.
if (nouvelIncident) {
    if (p.duree_cycle > 0) {
        flow.set("nb_rebuts", (flow.get("nb_rebuts") || 0) + 1);
        flow.set("cycle_interrompu", false);
        node.warn("Cycle avorte apres " + p.duree_cycle + " ms - piece rebutee");
    } else {
        flow.set("cycle_interrompu", true);
    }
}

// --- Libelle lisible de la cause ---
const causes = [];
if (/CAPOT/.test(codePropre)) { causes.push("capot ouvert"); }
if (/DCY/.test(codePropre))   { causes.push("départ cycle (DCY) relâché"); }
if (/RTH1/.test(codePropre))  { causes.push("défaut thermique moteur M1 (disque abrasif)"); }
if (/RTH2/.test(codePropre))  { causes.push("défaut thermique moteur M2 (entraînement câble)"); }
const libelle = causes.length ? causes.join(" + ") : null;

// Nature de l'arret memorisee pour l'IHM. Indispensable depuis que le
// firmware repete "ARRET_SECURITE" dans ses heartbeats : l'etat seul ne
// permet plus de distinguer un capot ouvert d'un defaut thermique, les
// quatre causes partageant le meme libelle d'etat.
flow.set("arret_exploitation", estIncident && !estPanne);

// Arret d'exploitation : information, jamais alarme, jamais de diagnostic IA
flow.set("raison_arret", (estIncident && !estPanne && libelle)
    ? ("Arrêt machine — " + libelle)
    : (etat === "ATTENTE" ? "En attente du départ cycle" : null));

if (!estPanne || !nouvelIncident) {
    node.status({ fill: estIncident ? "blue" : "green", shape: "ring",
                  text: etat + (libelle ? " (" + libelle + ")" : "") });
    return null;
}

// Quel moteur a declenche : le diagnostic sera cible sur cet organe
const m1 = /RTH1/.test(codePropre), m2 = /RTH2/.test(codePropre);
const moteur = (m1 && m2) ? "M1+M2" : (m1 ? "M1" : (m2 ? "M2" : null));

msg.payload = {
    type_alerte: "defaut",
    etat: etat,
    statut: "DEFAUT MACHINE - " + etat,
    code_defaut: p.defaut || p.code_defaut || null,
    libelle: libelle,
    moteur: moteur,
    nb_pieces: flow.get("nb_pieces") || 0,
    dernier_cycle: p.duree_cycle || null
};

node.status({ fill: "red", shape: "dot", text: "defaut : " + (libelle || etat) });
return msg;

// ============================================================
// PRECHAUFFER IA
// Charge llama3.2:1b en RAM au demarrage puis toutes les 30 min.
// Un appel a prompt vide suffit : Ollama repond done_reason "load"
// sans generer de texte (~6 s mesure sur ce poste). Sans ce
// prechauffage, ce delai s'ajoute au tout premier diagnostic reel.
//
// Chaine isolee : elle ne traverse ni le catch "Erreur IA" ni l'IHM.
// Si Ollama est arrete, ce message echoue sans aucun effet visible.
// ============================================================

msg.payload = {
    model: "llama3.2:1b",
    keep_alive: -1            // maintient le modele charge indefiniment
};
msg.requestTimeout = 30000;
return msg;

// ============================================================
// CHANGEMENT D'OUVRIER
// Saisi depuis le dashboard. Un poste appartient a un ouvrier : quand la
// releve arrive, on CLOTURE d'abord le poste en cours (archivage CSV +
// remise a zero des compteurs), puis on repart a zero pour le suivant.
// Sans cela, la production des deux ouvriers serait melangee et l'IHM,
// qui n'affiche que l'instant present, effacerait le travail du precedent.
// ============================================================

const nouveau = String(msg.payload || "").trim();
if (!nouveau) { return null; }

const ancien = flow.get("ouvrier") || "";
if (nouveau === ancien) { return null; }

const pieces = flow.get("nb_pieces") || 0;

// Poste vide (aucune piece produite) : rien a archiver, on nomme simplement
// l'ouvrier et on demarre son poste.
if (pieces === 0) {
    flow.set("ouvrier", nouveau);
    flow.set("debut_poste", Date.now());
    node.status({ fill: "green", shape: "dot", text: "poste : " + nouveau });
    return null;
}

// Sinon on cloture le poste de l'ancien avant de basculer.
node.status({ fill: "blue", shape: "dot", text: "releve : " + ancien + " -> " + nouveau });
msg.nouvel_ouvrier = nouveau;
msg.motif = "releve d'equipe";
return msg;

// Le classeur n'existe pas encore : le noeud "file in" leve une erreur,
// captee ici. On repart d'un contenu vide, SheetJS creera le fichier.
msg.payload = null;
node.status({ fill: "grey", shape: "ring", text: "classeur cree" });
return msg;

// ============================================================
// FUSIONNER CLASSEUR  --  ecriture d'un vrai fichier Excel
// Un seul classeur roufix_suivi.xlsx contient deux feuilles :
//   "Postes"      : une ligne par poste, avec l'ouvrier
//   "Diagnostics" : une ligne par diagnostic IA
// Le classeur existant est relu, la ligne ajoutee, puis le tout reecrit :
// les donnees s'accumulent sans jamais dupliquer l'en-tete.
// La bibliotheque SheetJS est declaree dans l'onglet "Configuration" du
// noeud (module "xlsx") : Node-RED l'installe automatiquement.
// ============================================================

const feuille = msg.feuille;
const entete = msg.entete;      // tableau des noms de colonnes
const ligne = msg.ligne;        // tableau des valeurs
if (!feuille || !Array.isArray(entete) || !Array.isArray(ligne)) { return null; }

// Classeur existant, ou classeur neuf si le fichier n'existe pas encore
let classeur;
if (msg.payload && msg.payload.length) {
    try {
        // cellStyles: true est indispensable — sans lui, la relecture
        // supprime les largeurs de colonnes des AUTRES feuilles, qui
        // seraient alors reecrites sans mise en forme.
        classeur = XLSX.read(msg.payload, { type: "buffer", cellStyles: true });
    } catch (e) {
        node.warn("Classeur illisible, il est recree : " + e.message);
        classeur = XLSX.utils.book_new();
    }
} else {
    classeur = XLSX.utils.book_new();
}

// Contenu actuel de la feuille, en tableau de tableaux
const existante = classeur.Sheets[feuille];
let lignes = existante ? XLSX.utils.sheet_to_json(existante, { header: 1 }) : [];
lignes = lignes.filter(l => l && l.length);

if (!lignes.length) { lignes.push(entete); }
lignes.push(ligne);

const nouvelle = XLSX.utils.aoa_to_sheet(lignes);

// Largeurs de colonnes et filtres : le tableau est lisible et triable
// des l'ouverture, sans manipulation.
nouvelle["!cols"] = msg.largeurs || entete.map(t => ({ wch: Math.max(10, String(t).length + 2) }));
nouvelle["!autofilter"] = { ref: XLSX.utils.encode_range({
    s: { r: 0, c: 0 },
    e: { r: lignes.length - 1, c: entete.length - 1 }
}) };

if (classeur.SheetNames.indexOf(feuille) === -1) {
    XLSX.utils.book_append_sheet(classeur, nouvelle, feuille);
} else {
    classeur.Sheets[feuille] = nouvelle;
}

msg.payload = XLSX.write(classeur, { type: "buffer", bookType: "xlsx" });
node.status({ fill: "green", shape: "dot", text: feuille + " : " + (lignes.length - 1) + " ligne(s)" });
return msg;

// ============================================================
// ARCHIVER DIAGNOSTIC
// Chaque diagnostic (reel ou repli) est consigne dans la feuille
// "Diagnostics" du classeur roufix_suivi.xlsx. L'IHM operateur n'affiche
// que l'instant present : ce classeur est la memoire longue du responsable.
// ============================================================

const CHEMIN = "C:/Users/GM Louay/OneDrive/Documents/roufix_suivi.xlsx";
const p = msg.payload || {};
if (!p.anomalie) { return null; }

const d = new Date();
const causes = Array.isArray(p.causes_probables) ? p.causes_probables.join(" / ") : "";
const spc = msg.spc || {};

msg.filename = CHEMIN;
msg.feuille = "Diagnostics";
msg.entete = ["Date", "Heure", "Ouvrier", "Nature", "Anomalie constatee",
              "Causes probables", "Action immediate", "Source",
              "Duree analyse (s)", "Cycle mesure (ms)", "Moyenne (ms)",
              "LIC (ms)", "LSC (ms)"];
msg.ligne = [
    d.toLocaleDateString('fr-FR'),
    d.toLocaleTimeString('fr-FR'),
    flow.get("ouvrier") || "Non renseigne",
    msg.famille || "derive",
    p.anomalie,
    causes,
    p.action_immediate || "",
    (p.fallback === true) ? "repli" : "IA",
    p.duree_ia ? Math.round(p.duree_ia / 100) / 10 : "",
    (spc.cycle != null) ? spc.cycle : "",
    (spc.moyenne != null) ? spc.moyenne : "",
    (spc.LIC != null) ? spc.LIC : "",
    (spc.LSC != null) ? spc.LSC : ""
];
msg.largeurs = [11, 10, 18, 10, 52, 46, 46, 9, 15, 16, 13, 11, 11].map(w => ({ wch: w }));

// Ce chemin ne doit surtout pas remettre les compteurs de poste a zero
msg.raz = false;
return msg;

// ============================================================
// PREPARER HISTORIQUE  --  alimente l'onglet du responsable
// Rassemble les postes archives et les diagnostics conserves en memoire,
// et les met en forme pour les deux tableaux du dashboard.
// ============================================================

const postes = flow.get("postes") || [];
const diagnostics = flow.get("diagnostics") || [];

// Synthese par ouvrier : de quoi comparer les equipes d'un coup d'oeil
const parOuvrier = {};
postes.forEach(function (p) {
    const cle = p.ouvrier || "Non renseigne";
    if (!parOuvrier[cle]) {
        parOuvrier[cle] = { ouvrier: cle, postes: 0, pieces: 0, minutes: 0, trs: 0, incidents: 0 };
    }
    const o = parOuvrier[cle];
    o.postes += 1;
    o.pieces += p.pieces || 0;
    o.minutes += p.duree_min || 0;
    o.trs += p.trs || 0;
    o.incidents += p.incidents || 0;
});
const synthese = Object.keys(parOuvrier).map(function (k) {
    const o = parOuvrier[k];
    return {
        ouvrier: o.ouvrier,
        postes: o.postes,
        pieces: o.pieces,
        heures: Math.round(o.minutes / 6) / 10,
        trs_moyen: Math.round((o.trs / o.postes) * 10) / 10,
        incidents: o.incidents,
        cadence: o.minutes > 0 ? Math.round((o.pieces / o.minutes) * 60) : 0
    };
}).sort(function (a, b) { return b.pieces - a.pieces; });

msg.payload = {
    maj: new Date().toLocaleTimeString('fr-FR'),
    poste_en_cours: {
        ouvrier: flow.get("ouvrier") || "Non renseigne",
        pieces: flow.get("nb_pieces") || 0,
        depuis_min: Math.round((Date.now() - (flow.get("debut_poste") || Date.now())) / 60000)
    },
    postes: postes,
    synthese: synthese,
    diagnostics: diagnostics,
    total_postes: postes.length,
    total_diagnostics: diagnostics.length
};
return msg;
